mapper.select:
SELECT prompt FROM prompt
WHERE id = #{promptId} AND tenant_id = #{tenantId} AND user_id = #{userId}
LIMIT 1

SELECT id, type, api_key AS apiKey, model_name AS modelName, base_url AS baseUrl, disabled, create_time AS createTime, update_time AS updateTime, created_by AS createdBy, company_id AS companyId FROM chat_model WHERE company_id = #{companyId}
AND model_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY create_time DESC

SELECT cd.*, CASE WHEN cd.directory_id = 'default' THEN '默认文件夹' ELSE cdd.DIRECTORY END AS directory_name FROM chat_doc cd LEFT JOIN chat_doc_directory cdd ON cd.directory_id = cdd.id AND cd.directory_id != 'default' WHERE cd.user_id = #{userId} AND cd.tenant_id = #{tenantId}
AND cd.permission = #{permission}
AND EXISTS ( SELECT 1 FROM tenant_user tu WHERE tu.tenant_id = #{tenantId} AND tu.user_id = #{userId} AND tu.disabled = 0 )

mapper.update:
UPDATE chat_model
SET disabled = 1,
update_time = NOW()
WHERE id = #{id}
AND company_id = #{companyId}

mapper.select:
SELECT role
FROM company_user
WHERE user_id = #{userId}
AND company_id = #{companyId}
AND status = 1
LIMIT 1

SELECT id
FROM `user`
WHERE disabled = 0
  AND (id = #{identifier}
       OR user_account = #{identifier}
       OR username = #{identifier})

SELECT COUNT(*)
FROM tenant_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND role = 2
  AND disabled = 0

SELECT COUNT(*)
FROM tenant_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND role IN (1, 2)
  AND disabled = 0

SELECT COUNT(*)
FROM tenant_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND disabled = 0

SELECT role
FROM tenant_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND disabled = 0
LIMIT 1

mapper.update:
UPDATE tenant_user tu
JOIN tenant_user admin
    ON admin.tenant_id = #{tenantId}
   AND admin.user_id = #{adminUserId}
   AND admin.role = 2
   AND admin.disabled = 0
SET tu.role = #{role},
    tu.create_by = #{adminUserId}
WHERE tu.tenant_id = #{tenantId}
  AND tu.user_id = #{userId}
  AND tu.disabled = 0

mapper.insert:
INSERT INTO tenant_user (id, tenant_id, user_id, role, join_date, create_by, disabled)
SELECT #{id}, #{tenantId}, #{userId}, 0, NOW(), #{adminUserId}, 0
FROM dual
WHERE EXISTS (
    SELECT 1 FROM tenant_user admin
    WHERE admin.tenant_id = #{tenantId}
      AND admin.user_id = #{adminUserId}
      AND admin.role IN (1, 2)
      AND admin.disabled = 0
)
AND NOT EXISTS (
    SELECT 1 FROM tenant_user tu
    WHERE tu.tenant_id = #{tenantId}
      AND tu.user_id = #{userId}
)

mapper.delete:
DELETE tu
FROM tenant_user tu
JOIN tenant_user admin
    ON admin.tenant_id = #{tenantId}
   AND admin.user_id = #{adminUserId}
   AND admin.role IN (1, 2)
   AND admin.disabled = 0
WHERE tu.tenant_id = #{tenantId}
  AND tu.user_id = #{userId}
  AND tu.user_id != #{adminUserId}

DELETE cu
FROM company_user cu
JOIN company_user admin
    ON admin.company_id = #{companyId}
   AND admin.user_id = #{adminUserId}
   AND admin.role >= 1
   AND admin.status = 1
WHERE cu.company_id = #{companyId}
  AND cu.user_id = #{userId}
  AND cu.user_id != #{adminUserId}
